package com.bank.rsocket.client;

import com.bank.rsocket.dto.BalanceResponse;
import com.bank.rsocket.dto.PriceTick;
import io.rsocket.core.RSocketConnector;
import io.rsocket.core.Resume;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.rsocket.RSocketRequester;
import reactor.core.publisher.Mono;
import reactor.util.retry.Retry;
import java.math.BigDecimal;
import java.net.ConnectException;
import java.time.Duration;

@Slf4j
public class ResilientTradingClient {
    private final RSocketRequester requester;

    public ResilientTradingClient(RSocketRequester.Builder builder) {
        // Keep-alive: ping every 20s, declare dead after 90s with no ack.
        // Resume: enable session resumption so drops reconnect transparently.
        this.requester = builder
            .rsocketConnector(connector -> connector
                .keepAlive(Duration.ofSeconds(20), Duration.ofSeconds(90))
                .resume(new Resume()
                    .retry(Retry.fixedDelay(5, Duration.ofSeconds(2)))))
            .tcp("localhost", 7000);
    }

    // Balance query with retry-on-transient + cached fallback.
    public Mono<BalanceResponse> balanceWithResilience(String accountId) {
        return requester.route("account.balance").data(accountId)
            .retrieveMono(BalanceResponse.class)
            // retry only TRANSIENT failures, exponential backoff + jitter
            .retryWhen(Retry.backoff(3, Duration.ofSeconds(1))
                .filter(this::isTransient)
                .doBeforeRetry(sig -> log.warn("Retrying balance for {} attempt {}",
                        accountId, sig.totalRetries() + 1)))
            // if all retries fail, serve a cached value instead of erroring
            .onErrorResume(ex -> {
                log.error("Balance call failed permanently, using cache", ex);
                return Mono.just(new BalanceResponse(accountId, cachedBalance(accountId)));
            });
    }

    // Price feed: survives disconnects via resumption; re-subscribe on hard error.
    public void subscribePrices(String symbol) {
        requester.route("price.stream").data(symbol)
            .retrieveFlux(PriceTick.class)
            .limitRate(3)
            .retryWhen(Retry.fixedDelay(Long.MAX_VALUE, Duration.ofSeconds(2))
                .filter(this::isTransient)) // reconnect on transient drops
            .subscribe(t -> log.info("Tick {} Rs.{}", t.seq(), t.price()),
                       err -> log.error("Price stream ended", err));
    }

    private boolean isTransient(Throwable t) {
        return t instanceof ConnectException
            || t.getMessage() != null && t.getMessage().contains("connection");
    }

    private BigDecimal cachedBalance(String id) {
        return "SAV2001".equals(id) ? new BigDecimal("1000000") : new BigDecimal("250000");
    }
}
