package com.bank.rsocket.controller;

import com.bank.rsocket.dto.BalanceResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.handler.annotation.MessageExceptionHandler;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Mono;
import java.math.BigDecimal;

@Slf4j
@Controller
public class PriceController {

    @MessageMapping("account.balance")
    public Mono<BalanceResponse> balance(String accountId) {
        if (accountId == null || accountId.isBlank())
            return Mono.error(new IllegalArgumentException("accountId required"));
        BigDecimal bal = "SAV2001".equals(accountId)
            ? new BigDecimal("1000000") : new BigDecimal("250000");
        return Mono.just(new BalanceResponse(accountId, bal));
    }

    // Central server-side error mapping → client sees a clean message, not a stack trace.
    @MessageExceptionHandler
    public Mono<String> handle(IllegalArgumentException ex) {
        log.error("Validation error mapped to client", ex);
        return Mono.just("ERROR: " + ex.getMessage());
    }
}
